{
  "nodes_info": [
    {
      "id": "1",
      "type": "start",
      "param": {
        "variables": [
          ["case_input", "string"],
          ["source_language", "string"]
        ]
      }
    },
    {
      "id": "2",
      "type": "llm",
      "param": {
        "system": "You are a code validation and translation expert. First, check if the provided code in the specified language is syntactically correct and well-formed. If the code is invalid, output ONLY: 'ERROR: Invalid code format or syntax'. If the code is valid, translate it to Python while preserving all functionality. Ensure the translation is executable Python code.",
        "user": "Source language: {{#1.source_language#}}\n\nCode to validate and translate:\n{{#1.case_input#}}\n\nOutput ONLY the error message or the translated Python code:"
      }
    },
    {
      "id": "3",
      "type": "code",
      "param": {
        "variables": [
          ["python_code", ["text", "2"]]
        ],
        "outputs": [
          ["result", "string"]
        ],
        "code": "def main(python_code: str):\n\timport sys\n\tfrom io import StringIO\n\t\n\t# Check if it's an error message from LLM\n\tif python_code.startswith('ERROR:'):\n\t\treturn {\"result\": python_code}\n\t\n\ttry:\n\t\t# Capture stdout\n\t\told_stdout = sys.stdout\n\t\tsys.stdout = StringIO()\n\t\t\n\t\t# Execute the code\n\t\texec(python_code, {})\n\t\t\n\t\t# Get the output\n\t\toutput = sys.stdout.getvalue()\n\t\tsys.stdout = old_stdout\n\t\t\n\t\t# If no output, indicate successful execution\n\t\tif not output:\n\t\t\toutput = \"Code executed successfully (no output)\"\n\t\t\n\t\treturn {\"result\": output}\n\t\t\n\texcept Exception as e:\n\t\t# Restore stdout\n\t\tsys.stdout = old_stdout\n\t\treturn {\"result\": f\"Execution error: {str(e)}\"}"
      }
    },
    {
      "id": "4",
      "type": "end",
      "param": {
        "outputs": [
          ["python_code", ["text", "2"]],
          ["result", ["result", "3"]]
        ]
      }
    }
  ],
  "edges": [
    ["1", 0, "2"],
    ["2", 0, "3"],
    ["3", 0, "4"]
  ]
}

