        "variables": [["exam_image", "file"]]
      }
    },
    {
      "id": "2",
      "type": "llm",
      "param": {
        "system": "You are an educational assistant specializing in exam analysis. Extract incorrect questions from student exam papers and format them into a structured error notebook.",
        "user": "Analyze this exam paper image and identify all incorrect answers. For each incorrect question, extract:
1. question_text: The full question text
2. subject: The subject area (e.g., Math, Science, English)
3. question_type: Classify as Multiple Choice, Fill-in-the-Blank, True/False, or Short Answer
4. difficulty: Rate 1-5 (1=easiest, 5=hardest)
5. answer: The correct answer
6. user_answer: The student's incorrect answer
7. explanation: Why the student's answer was wrong and the correct approach

Format the output as a JSON array of objects with these exact field names. Only include questions the student answered incorrectly.

Exam paper: {{#'1'.exam_image#}}"
      }
    },
    {
      "id": "3",
      "type": "code",
      "param": {
        "variables": [["llm_output", ["text", "2"]]],
        "outputs": [["error_notebook", "array[object]"]],
        "code": "def main(llm_output: str):
	import json
	import re

	# Extract JSON from LLM output (handles cases where LLM adds explanatory text)
	json_match = re.search(r'\[.*\]', llm_output, re.DOTALL)
	if json_match:
		json_str = json_match.group()
	else:
		json_str = llm_output

	# Parse and validate structure
	try:
		data = json.loads(json_str)

		# Ensure it's a list
		if not isinstance(data, list):
			data = [data]

		# Validate each object has required fields
		required_fields = {'question_text', 'subject', 'question_type', 'difficulty', 'answer', 'user_answer', 'explanation'}
		validated_data = []

		for item in data:
			if isinstance(item, dict):
				# Check for missing fields
				missing = required_fields - set(item.keys())
				if not missing:
					# Ensure difficulty is numeric
					if 'difficulty' in item:
						try:
							item['difficulty'] = int(item['difficulty'])
							if item['difficulty'] < 1:
								item['difficulty'] = 1
							elif item['difficulty'] > 5:
								item['difficulty'] = 5
						except:
							item['difficulty'] = 3
					validated_data.append(item)

		return {"error_notebook": validated_data}
